"  const getPrinterConfig = (orderTypeKey, jobType) => {
    let key = String(orderTypeKey || '').toUpperCase().replace('-', '_').trim();
    if (key.includes('PRE_ORDER') || key.includes('PREORDER')) {
      key = 'PRE_ORDER';
    } else if (key.includes('DELIVERY')) {
      key = 'DELIVERY';
    } else if (key.includes('PICKUP') || key === 'TAKEAWAY' || key === 'PICK_UP') {
      key = 'PICKUP';
    } else if (key.includes('QUICK')) {
      key = 'QUICK';
    } else if (key.includes('DINE_IN') || key.includes('DINEIN')) {
      key = 'DINE_IN';
    } else {
      key = 'DINE_IN';
    }

    const printers = posSettings.orderPrinters || {};
    const configGroup = printers[key] || {};
    const jobConfig = configGroup[jobType] || {};

    let resolvedNames = [];
    if (Array.isArray(jobConfig.names) && jobConfig.names.length > 0) {
      resolvedNames = jobConfig.names;
    } else if (jobConfig.name) {
      resolvedNames = [jobConfig.name];
    } else if (posSettings.printerName) {
      resolvedNames = [posSettings.printerName];
    } else {
      resolvedNames = ['Default Thermal Printer'];
    }

    return {
      enabled: jobConfig.enabled !== false,
      names: resolvedNames,
      name: resolvedNames[0] || '',
      paperSize: jobConfig.paperSize || posSettings.printerType || 'THERMAL_80MM'
    };
  };"

