"  const getPrinterConfig = (orderTypeKey, jobType) => {
    let key = String(orderTypeKey || '').toUpperCase().replace('-', '_');
    if (key === 'TAKEAWAY' || key === 'PICK_UP') key = 'PICKUP';
    if (key === 'QUICK_BILL') key = 'QUICK';

    const printers = posSettings.orderPrinters || {};
    const configGroup = printers[key] || {
      kot: { enabled: true, name: '', paperSize: 'THERMAL_80MM' },
      bill: { enabled: true, name: '', paperSize: 'THERMAL_80MM' }
    };
    return configGroup[jobType] || { enabled: true, name: '', paperSize: 'THERMAL_80MM' };
  };"
